const ADMIN_STATUSES=['pending_confirmation'=>'Chờ xác nhận','pending_quote'=>'Chờ báo giá','confirmed'=>'Đã xác nhận','packing'=>'Đang chuẩn bị','shipping'=>'Đang giao','completed'=>'Hoàn tất','cancelled'=>'Đã hủy'];
function admin_private(): string {return PHP_SAPI==='cli'&&defined('VICTOR_ADMIN_TEST_DIR')?VICTOR_ADMIN_TEST_DIR:dirname(__DIR__,2).'/thevictor-private';}
function h($value): string {return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function admin_headers(): void {header('Cache-Control: no-store, private');header('X-Robots-Tag: noindex, nofollow');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');header('X-Frame-Options: DENY');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; form-action 'self'; base-uri 'none'");}
function admin_init(): void {
 admin_headers();if(empty($_SERVER['HTTPS'])||$_SERVER['HTTPS']==='off'){http_response_code(400);exit('Vui lòng sử dụng HTTPS.');}
 $dir=admin_private().'/admin-sessions';if(!is_dir($dir))mkdir($dir,0700,true);session_save_path($dir);ini_set('session.use_strict_mode','1');ini_set('session.gc_maxlifetime','28800');session_name('victor_admin');session_set_cookie_params(['lifetime'=>0,'path'=>'/quan-tri/','secure'=>true,'httponly'=>true,'samesite'=>'Strict']);session_start();
 if(!empty($_SESSION['admin'])&&(time()-($_SESSION['last_seen']??0)>1800||time()-($_SESSION['login_at']??0)>28800)){$_SESSION=[];session_regenerate_id(true);}
 if(!empty($_SESSION['admin']))$_SESSION['last_seen']=time();
 if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));
}
function admin_config(): ?array {$file=admin_private().'/admin-config.json';return is_file($file)?json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR):null;}
require_once __DIR__.'/team.php';
function admin_logged_in(): bool {return team_identity()!==null;}
function admin_csrf(): void {if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['csrf']??'',$_POST['csrf']))throw new RuntimeException('Phiên làm việc đã thay đổi. Vui lòng tải lại trang.',403);}
function admin_login(string $username,string $password): bool {
 $db=new PDO('sqlite:'.admin_private().'/admin-auth.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$db->exec('PRAGMA busy_timeout=5000; CREATE TABLE IF NOT EXISTS attempts(ip TEXT PRIMARY KEY, started INTEGER NOT NULL, failures INTEGER NOT NULL)');@chmod(admin_private().'/admin-auth.sqlite',0600);$key=hash('sha256',$_SERVER['REMOTE_ADDR']??'unknown');$now=time();$db->beginTransaction();$q=$db->prepare('SELECT * FROM attempts WHERE ip=?');$q->execute([$key]);$row=$q->fetch(PDO::FETCH_ASSOC);if($row&&$now-(int)$row['started']<900&&(int)$row['failures']>=8){$db->commit();throw new RuntimeException('Đăng nhập sai quá nhiều lần. Vui lòng thử lại sau 15 phút.',429);}
 $config=admin_config();$staff=null;if($config&&!hash_equals($config['username'],$username)){$q=team_db()->prepare('SELECT * FROM staff WHERE username=? AND active=1');$q->execute([$username]);$staff=$q->fetch()?:null;}$hash=$staff['password_hash']??$config['password_hash']??'$2y$10$X5R6iGk6akJ7xPPL3KbV9eopn2r1yQ9g6rWrsE95zG0KnKkx6oNfK';$valid=password_verify($password,$hash)&&$config&&($staff!==null||hash_equals($config['username'],$username));
 if($valid){$q=$db->prepare('DELETE FROM attempts WHERE ip=?');$q->execute([$key]);$db->commit();session_regenerate_id(true);$_SESSION=['admin'=>true,'auth_version'=>$staff['version']??$config['version'],'login_at'=>$now,'last_seen'=>$now,'csrf'=>bin2hex(random_bytes(32))];if($staff)$_SESSION['staff_id']=(int)$staff['id'];return true;}
 $within=$row&&$now-(int)$row['started']<900;$started=$within?(int)$row['started']:$now;$count=$within?(int)$row['failures']+1:1;$q=$db->prepare('INSERT INTO attempts(ip,started,failures) VALUES(?,?,?) ON CONFLICT(ip) DO UPDATE SET started=excluded.started, failures=excluded.failures');$q->execute([$key,$started,$count]);$db->commit();usleep(350000);return false;
}
function setup_grant_valid(): bool {$file=admin_private().'/admin-setup.json';if(admin_config()||!is_file($file))return false;$grant=json_decode(file_get_contents($file),true);return ($grant['expires']??0)>time()&&hash_equals($grant['token_hash'],(string)($_SESSION['setup_grant']??''));}
function create_admin(string $username,string $password,string $confirmation): void {
 if(!setup_grant_valid())throw new RuntimeException('Liên kết kích hoạt không hợp lệ hoặc đã hết hạn.',403);
 if(!preg_match('/^[a-zA-Z0-9_.-]{3,50}$/',$username))throw new RuntimeException('Tên đăng nhập cần 3–50 ký tự: chữ không dấu, số, dấu chấm, gạch ngang hoặc gạch dưới.',400);
 if(strlen($password)<12||strlen($password)>72)throw new RuntimeException('Mật khẩu cần từ 12 đến 72 ký tự.',400);
 if(!hash_equals($password,$confirmation))throw new RuntimeException('Hai mật khẩu chưa khớp.',400);
 $config=['username'=>$username,'password_hash'=>password_hash($password,PASSWORD_DEFAULT),'version'=>bin2hex(random_bytes(16)),'created_at'=>gmdate('c')];$file=admin_private().'/admin-config.json';$handle=fopen($file,'x');if(!$handle)throw new RuntimeException('Trang quản trị đã được kích hoạt.',409);chmod($file,0600);try{if(fwrite($handle,json_encode($config,JSON_THROW_ON_ERROR))===false)throw new RuntimeException('Không lưu được cấu hình.',500);}finally{fclose($handle);}unset($_SESSION['setup_grant']);session_regenerate_id(true);$_SESSION=['admin'=>true,'auth_version'=>$config['version'],'login_at'=>time(),'last_seen'=>time(),'csrf'=>bin2hex(random_bytes(32))];
}
function admin_db(): PDO {$file=admin_private().'/orders.sqlite';if(!is_file($file))throw new RuntimeException('Chưa có cơ sở dữ liệu đơn hàng.',503);$db=new PDO('sqlite:'.$file,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$db->sqliteCreateFunction('vi_lower',static fn($text)=>mb_strtolower((string)$text,'UTF-8'),1);$db->exec('PRAGMA busy_timeout=5000; CREATE TABLE IF NOT EXISTS order_admin_meta(code TEXT PRIMARY KEY, note TEXT NOT NULL DEFAULT "", version INTEGER NOT NULL DEFAULT 0, updated_at TEXT); CREATE TABLE IF NOT EXISTS order_admin_audit(id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL, old_status TEXT NOT NULL, new_status TEXT NOT NULL, old_note TEXT NOT NULL, new_note TEXT NOT NULL, changed_at TEXT NOT NULL, actor TEXT NOT NULL)');stats_schema($db);$db->exec('CREATE TABLE IF NOT EXISTS order_admin_numbers(number INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL UNIQUE); INSERT OR IGNORE INTO order_admin_numbers(code) SELECT code FROM orders WHERE NOT EXISTS(SELECT 1 FROM order_admin_numbers n WHERE n.code=orders.code) ORDER BY created_at,code');return $db;}
function order_filters(array $input): array {
 $clauses=[(string)($input['trash']??'')==='1'?'EXISTS(SELECT 1 FROM order_admin_trash t WHERE t.code=o.code)':'NOT EXISTS(SELECT 1 FROM order_admin_trash t WHERE t.code=o.code)'];$params=[];$q=trim((string)($input['q']??''));if(mb_strlen($q)>100)throw new RuntimeException('Từ khóa quá dài.',400);if($q!==''){$pattern='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$q).'%';$clauses[]="(o.code LIKE ? ESCAPE '\' OR vi_lower(json_extract(o.payload,'$.customerName')) LIKE vi_lower(?) ESCAPE '\' OR json_extract(o.payload,'$.phone') LIKE ? ESCAPE '\')";array_push($params,$pattern,$pattern,$pattern);}
 $status=(string)($input['status']??'');if($status!==''){if(!isset(ADMIN_STATUSES[$status]))throw new RuntimeException('Trạng thái không hợp lệ.',400);$clauses[]='o.status=?';$params[]=$status;}
 foreach(['from','to'] as $key){$text=(string)($input[$key]??'');if($text==='')continue;$date=DateTimeImmutable::createFromFormat('!Y-m-d',$text,new DateTimeZone('Asia/Ho_Chi_Minh'));if(!$date||$date->format('Y-m-d')!==$text)throw new RuntimeException('Ngày chưa hợp lệ.',400);if($key==='to')$date=$date->modify('+1 day');$clauses[]=$key==='from'?'o.created_at>=?':'o.created_at<?';$params[]=$date->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z');}
 return [$clauses?' WHERE '.implode(' AND ',$clauses):'',$params];
}
function admin_order(array $row): array {$data=json_decode($row['payload'],true,512,JSON_THROW_ON_ERROR);return ['number'=>(int)($row['order_no']??0),'code'=>$row['code'],'createdAt'=>$row['created_at'],'status'=>$row['status'],'customerName'=>$data['customerName'],'phone'=>$data['phone'],'age'=>$data['age']??null,'height'=>$data['height']??null,'weight'=>$data['weight']??null,'address'=>$data['address'],'note'=>$data['note']??'','items'=>$data['items'],'total'=>$data['total'],'shippingFee'=>$data['shippingFee']??0,'internalNote'=>$row['admin_note']??'','version'=>(int)($row['admin_version']??0),'updatedAt'=>$row['admin_updated']??null];}
function admin_update(PDO $db,array $input,string $actor): array {
 $code=(string)($input['code']??'');$status=(string)($input['status']??'');$note=trim((string)($input['internalNote']??''));$version=$input['version']??null;if(!preg_match('/^TV-[A-F0-9]{12}$/',$code)||!isset(ADMIN_STATUSES[$status])||!is_int($version)||$version<0||mb_strlen($note)>2000)throw new RuntimeException('Thông tin cập nhật không hợp lệ.',400);
 $db->beginTransaction();try{$q=$db->prepare('SELECT o.*,m.note AS admin_note,m.version AS admin_version,m.updated_at AS admin_updated FROM orders o LEFT JOIN order_admin_meta m ON m.code=o.code WHERE o.code=?');$q->execute([$code]);$row=$q->fetch();if(!$row)throw new RuntimeException('Không tìm thấy đơn hàng.',404);if((int)($row['admin_version']??0)!==$version)throw new RuntimeException('Đơn đã được cập nhật ở nơi khác. Vui lòng tải lại trước khi lưu.',409);$now=gmdate('Y-m-d\TH:i:s\Z');$q=$db->prepare('UPDATE orders SET status=? WHERE code=?');$q->execute([$status,$code]);$q=$db->prepare('INSERT INTO order_admin_meta(code,note,version,updated_at) VALUES(?,?,?,?) ON CONFLICT(code) DO UPDATE SET note=excluded.note,version=excluded.version,updated_at=excluded.updated_at');$q->execute([$code,$note,$version+1,$now]);$q=$db->prepare('INSERT INTO order_admin_audit(code,old_status,new_status,old_note,new_note,changed_at,actor) VALUES(?,?,?,?,?,?,?)');$q->execute([$code,$row['status'],$status,$row['admin_note']??'',$note,$now,$actor]);$db->commit();return ['version'=>$version+1,'updatedAt'=>$now];}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
function admin_manual(PDO $db,array $input,string $actor): array {
 $source=$input['source']??'';if(!in_array($source,['meta_phone','meta_messenger','phone','messenger'],true))throw new RuntimeException('Vui lòng chọn nguồn đơn.',400);
 if(!defined('VICTOR_API_TEST'))define('VICTOR_API_TEST',true);require_once dirname(__DIR__).'/api/orders.php';$catalog=stats_catalog();$order=normalize_order($input+['consent'=>true],$catalog['products'],$catalog['sizes']);$owner='admin:'.$actor;$payload=json_encode($order,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$channel=str_contains($source,'messenger')?'messenger':'phone';$origin=str_starts_with($source,'meta_')?'meta':'offline';
 $db->beginTransaction();try{$q=$db->prepare('SELECT code,payload FROM orders WHERE owner=? AND request_key=?');$q->execute([$owner,$order['requestKey']]);if($existing=$q->fetch()){if($existing['payload']!==$payload)throw new RuntimeException('Nội dung đơn đã thay đổi. Vui lòng mở lại biểu mẫu.',409);$db->commit();return ['code'=>$existing['code']];}
 $code='TV-'.strtoupper(bin2hex(random_bytes(6)));$now=gmdate('Y-m-d\TH:i:s\Z');$q=$db->prepare('INSERT INTO orders(code,owner,request_key,created_at,status,payload,ip_hash) VALUES(?,?,?,?,?,?,?)');$q->execute([$code,$owner,$order['requestKey'],$now,$order['status'],$payload,'manual']);$q=$db->prepare('INSERT INTO order_sources(code,source,channel) VALUES(?,?,?)');$q->execute([$code,$origin,$channel]);$q=$db->prepare('INSERT INTO order_admin_audit(code,old_status,new_status,old_note,new_note,changed_at,actor) VALUES(?,?,?,?,?,?,?)');$q->execute([$code,$order['status'],$order['status'],'','Tạo đơn thủ công: '.$source,$now,$actor]);$db->commit();return ['code'=>$code];
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}

function admin_trash(PDO $db,array $input,string $actor): array {
 $codes=$input['codes']??null;$restore=($input['action']??'')==='restore';
 if(!is_array($codes)||!array_is_list($codes)||!count($codes)||count($codes)>100)throw new RuntimeException('Vui lòng chọn từ 1 đến 100 đơn.',400);
 foreach($codes as $code)if(!is_string($code)||!preg_match('/^TV-[A-F0-9]{12}$/',$code))throw new RuntimeException('Mã đơn không hợp lệ.',400);
 $codes=array_values(array_unique($codes));$db->beginTransaction();try{
 $find=$db->prepare('SELECT status FROM orders WHERE code=?');$now=gmdate('Y-m-d\TH:i:s\Z');$changed=0;
 foreach($codes as $code){$find->execute([$code]);$status=$find->fetchColumn();if($status===false)throw new RuntimeException('Không tìm thấy đơn hàng. Vui lòng tải lại.',404);
 $q=$db->prepare($restore?'DELETE FROM order_admin_trash WHERE code=?':'INSERT OR IGNORE INTO order_admin_trash(code,deleted_at,actor) VALUES(?,?,?)');$q->execute($restore?[$code]:[$code,$now,$actor]);if($q->rowCount()){$changed++;$audit=$db->prepare('INSERT INTO order_admin_audit(code,old_status,new_status,old_note,new_note,changed_at,actor) VALUES(?,?,?,?,?,?,?)');$audit->execute([$code,$status,$status,'',$restore?'Khôi phục từ Thùng rác':'Chuyển vào Thùng rác',$now,$actor]);}}
 $db->commit();return ['changed'=>$changed];}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}


function admin_phone_key($phone): string {
 if(!is_string($phone))return '';$phone=preg_replace('/[\s().-]+/u','',trim($phone));if(preg_match('/^\+84([0-9]{9})$/D',$phone,$m)||preg_match('/^84([0-9]{9})$/D',$phone,$m))$phone='0'.$m[1];return preg_match('/^0[0-9]{9}$/D',$phone)?$phone:'';
}
function admin_duplicate_phones(PDO $db,array $orders): array {
 $db->sqliteCreateFunction('victor_phone_key','admin_phone_key',1);$db->exec('CREATE INDEX IF NOT EXISTS orders_created_at ON orders(created_at)');
 $q=$db->prepare("SELECT o.code,n.number FROM orders o LEFT JOIN order_admin_numbers n ON n.code=o.code WHERE o.created_at>=? AND o.created_at<=? AND o.code<>? AND victor_phone_key(json_extract(o.payload,'$.phone'))=? AND NOT EXISTS(SELECT 1 FROM order_admin_trash t WHERE t.code=o.code) ORDER BY n.number ASC");
 foreach($orders as &$o){$o['duplicatePhone']=false;$o['duplicatePhoneCount']=0;$o['duplicateOrders']=[];$key=admin_phone_key($o['phone']??null);$time=strtotime($o['createdAt']??'');if($key===''||$time===false)continue;$q->execute([gmdate('Y-m-d\TH:i:s\Z',$time-48*3600),gmdate('Y-m-d\TH:i:s\Z',$time+48*3600),$o['code'],$key]);$matches=$q->fetchAll(PDO::FETCH_ASSOC);$o['duplicateOrders']=array_map(static fn($row)=>['code'=>$row['code'],'number'=>$row['number']===null?null:(int)$row['number']],$matches);$other=count($matches);$o['duplicatePhone']=$other>0;$o['duplicatePhoneCount']=$other?1+$other:0;}unset($o);return admin_duplicate_ips($db,$orders);
}

function admin_duplicate_ips(PDO $db,array $orders): array {
 $lookup=$db->prepare('SELECT ip_hash FROM orders WHERE code=?');$q=$db->prepare("SELECT o.code,n.number FROM orders o LEFT JOIN order_admin_numbers n ON n.code=o.code WHERE o.ip_hash=? AND o.code<>? AND o.created_at>=? AND o.created_at<=? AND NOT EXISTS(SELECT 1 FROM order_admin_trash t WHERE t.code=o.code) ORDER BY n.number ASC");
 foreach($orders as &$o){$o['duplicateIpOrders']=[];$time=strtotime($o['createdAt']??'');if($time===false)continue;$lookup->execute([$o['code']]);$hash=$lookup->fetchColumn();if(!is_string($hash)||!preg_match('/^[a-f0-9]{64}$/D',$hash))continue;$q->execute([$hash,$o['code'],gmdate('Y-m-d\TH:i:s\Z',$time-48*3600),gmdate('Y-m-d\TH:i:s\Z',$time+48*3600)]);$o['duplicateIpOrders']=array_map(static fn($r)=>['code'=>$r['code'],'number'=>$r['number']===null?null:(int)$r['number']],$q->fetchAll(PDO::FETCH_ASSOC));}unset($o);return $orders;
}
